package com.whaa.shop.order.infrastructure; import com.baomidou.mybatisplus.core.mapper.BaseMapper; import com.whaa.shop.order.domain.*; import org.apache.ibatis.annotations.*; import java.time.LocalDateTime;
public interface OrderMapper extends BaseMapper<ShopOrder>{@Update("update shop_order set status=#{to}, shipped_at=case when #{to}='SHIPPED' then #{now} else shipped_at end, completed_at=case when #{to}='COMPLETED' then #{now} else completed_at end, version=version+1 where id=#{id} and status=#{from}")int transition(@Param("id")Long id,@Param("from")String from,@Param("to")String to,@Param("now")LocalDateTime now);@Update("update shop_order set status='PAID',paid_at=#{now},version=version+1 where order_no=#{orderNo} and status='PENDING_PAYMENT' and total_amount=#{amount}")int markPaid(@Param("orderNo")String orderNo,@Param("amount")java.math.BigDecimal amount,@Param("now")LocalDateTime now);}
